def invert_multimap(mapping):
    """
    Invert a multimap from owners -> list of tags to tags -> list of owners.

    The order of owners in each list follows the order of keys in the input
    mapping. Duplicate tags for the same owner are ignored, i.e., an owner
    appears at most once per tag.
    """
    result = {}
    # Keep a set per tag to avoid duplicate owners
    seen = {}

    for owner, tags in mapping.items():
        for tag in tags:
            if tag not in result:
                result[tag] = []
                seen[tag] = set()
            if owner not in seen[tag]:
                result[tag].append(owner)
                seen[tag].add(owner)

    return result

