def quantile(values, q):
    if not values or q < 0 or q > 1:
        raise ValueError("Invalid input")
    sorted_values = sorted(values)
    n = len(sorted_values)
    p = (n - 1) * q
    k = int(p)
    d = p - k
    if k == n - 1:
        return sorted_values[k]
    return sorted_values[k] + d * (sorted_values[k + 1] - sorted_values[k])

